/** Short names for expected identities: the source ref is unique in this corpus. */
export const REF = {
  repo: REPO,
  pr: (n: number) => `${REPO}#pull/${n}`,
  issue: (n: number) => `${REPO}#issue/${n}`,
  jira: (key: string) => `jira:OPS#issue/${key}`,
  page: (id: string) => `confluence:ENG#page/${id}`,
};

export interface SearchCase {
  readonly name: string;
  readonly query: string;
  readonly outcome: 'match' | 'ambiguous' | 'no-match' | 'invalid-query';
  /** Expected hit source refs, in order. */
  readonly refs: readonly string[];
  readonly status?: readonly string[];
}

